def compress_runs_min_length(s, min_run):
    from itertools import groupby
    if not s:
        return ''
    parts = []
    for ch, group in groupby(s):
        run = list(group)
        length = len(run)
        if length >= min_run:
            parts.append(ch + str(length))
        else:
            parts.append(ch * length)
    return ''.join(parts)

